/**
 * Settings → Plugins card for `dsh-audio-model-library`: GPU servers and how to activate their models.
 * Stores host names, SSH aliases and environment-variable NAMES only — never keys, tokens or passwords.
 */

import { useState, useSyncExternalStore } from 'react'
import type { LibraryStore } from './store.ts'
import { format, type LibraryKey } from './locale.ts'
import css from './library.module.css'

interface ServerSetting {
  id: string
  displayName: string
  modelHost?: string
  apiKeyEnv?: string
  catalogFile?: string
  controller?: { mode: 'none' | 'ssh' | 'http', sshDestination?: string, sshCommand?: string, httpURL?: string, tokenEnv?: string }
}

export interface SettingsFace {
  scope: {
    getSnapshot(): { status: 'loading' | 'ready' | 'unavailable', value: { servers?: ServerSetting[] } | undefined, writable: boolean }
    subscribe(listener: () => void): () => void
    mutate(ops: ReadonlyArray<{ op: 'set', path: readonly string[], value: unknown }>): Promise<void>
  }
  store: LibraryStore
  openLibrary(): void
}

const HOST = /^(?:[A-Za-z0-9](?:[A-Za-z0-9-]{0,62}[A-Za-z0-9])?)(?:\.[A-Za-z0-9](?:[A-Za-z0-9-]{0,62}[A-Za-z0-9])?)*$|^\[[0-9A-Fa-f:.]+\]$/
const SSH_DEST = /^[A-Za-z0-9_][A-Za-z0-9_.@-]{0,254}$/
const ENV = /^[A-Za-z_][A-Za-z0-9_]*$/

function slug(text: string): string {
  const base = text.normalize('NFKD').toLowerCase().replaceAll(/[^a-z0-9]+/gu, '-').replaceAll(/^-+|-+$/gu, '').slice(0, 32)
  return base === '' ? 'gpu-server' : base
}

const EMPTY = { name: '', modelHost: '', mode: 'ssh', sshDestination: '', sshCommand: 'dsh-audio-ctl', httpURL: '', tokenEnv: '', catalogFile: '', apiKeyEnv: '' }

export function SettingsCard(props: any) {
  const t = (key: LibraryKey, values?: Record<string, string>) => format(props.t(key), values)
  const face: SettingsFace = props.librarySettings
  const settings = useSyncExternalStore(face.scope.subscribe, face.scope.getSnapshot)
  const [open, setOpen] = useState(false)
  const [form, setForm] = useState(EMPTY)
  const [invalid, setInvalid] = useState<string[]>([])
  const [status, setStatus] = useState('')
  const [saving, setSaving] = useState(false)
  if (settings.status === 'unavailable') return null
  const servers: ServerSetting[] = Array.isArray(settings.value?.servers) ? settings.value!.servers! : []
  const writable = settings.writable

  const write = async (next: ServerSetting[]) => {
    setSaving(true)
    setStatus(t('saving'))
    try {
      await face.scope.mutate([{ op: 'set', path: ['servers'], value: next }])
      const after = face.scope.getSnapshot().value?.servers ?? []
      // A refused write does not throw in settingsScope: compare what the host now holds.
      if (JSON.stringify(after.map(s => s.id)) !== JSON.stringify(next.map(s => s.id))) throw new Error('the host refused the update')
      setStatus(t('saved'))
      void face.store.load()
      return true
    } catch (error) {
      setStatus(t('saveFailed', { message: error instanceof Error ? error.message : String(error) }))
      return false
    } finally {
      setSaving(false)
    }
  }

  const add = async () => {
    const problems: string[] = []
    if (form.name.trim() === '') problems.push('name')
    if (!HOST.test(form.modelHost.trim())) problems.push('modelHost')
    if (form.mode === 'ssh' && !SSH_DEST.test(form.sshDestination.trim())) problems.push('sshDestination')
    if (form.mode === 'http' && !/^https?:\/\/[^\s/@]+/u.test(form.httpURL.trim())) problems.push('httpURL')
    if (form.mode === 'http' && !ENV.test(form.tokenEnv.trim())) problems.push('tokenEnv')
    if (form.catalogFile.trim() !== '' && !form.catalogFile.trim().startsWith('/')) problems.push('catalogFile')
    if (form.apiKeyEnv.trim() !== '' && !ENV.test(form.apiKeyEnv.trim())) problems.push('apiKeyEnv')
    setInvalid(problems)
    if (problems.length > 0) { setStatus(t('invalid')); return }
    const taken = new Set(servers.map(s => s.id))
    let id = slug(form.name)
    for (let n = 2; taken.has(id); n++) id = `${slug(form.name)}-${n}`
    const controller = form.mode === 'ssh'
      ? { mode: 'ssh' as const, sshDestination: form.sshDestination.trim(), sshCommand: form.sshCommand.trim() || 'dsh-audio-ctl' }
      : form.mode === 'http' ? { mode: 'http' as const, httpURL: form.httpURL.trim(), tokenEnv: form.tokenEnv.trim() } : { mode: 'none' as const }
    const server: ServerSetting = {
      id,
      displayName: form.name.trim(),
      modelHost: form.modelHost.trim(),
      controller,
      ...(form.catalogFile.trim() !== '' ? { catalogFile: form.catalogFile.trim() } : {}),
      ...(form.apiKeyEnv.trim() !== '' ? { apiKeyEnv: form.apiKeyEnv.trim() } : {}),
    }
    if (await write([...servers, server])) setForm(EMPTY)
  }

  const field = (key: keyof typeof EMPTY, label: LibraryKey, hint?: LibraryKey, placeholder?: string) => (
    <label className={css.field}>
      <span className={css.label}>{t(label)}</span>
      <input className={`${css.input} ${invalid.includes(key) ? css.inputBad : ''}`} value={form[key]} placeholder={placeholder} disabled={!writable} aria-invalid={invalid.includes(key)} onChange={(event) => { setForm({ ...form, [key]: event.target.value }) }} data-testid={`library-field-${key}`} />
      {hint ? <span className={css.hint}>{t(hint)}</span> : null}
    </label>
  )

  return (
    <li className={`${css.card} ${open ? css.cardOpen : ''}`} data-testid="library-settings-card">
      <button type="button" className={css.cardHeader} aria-expanded={open} onClick={() => { setOpen(!open) }}>
        <span className={css.cardText}>
          <span className={css.cardName}>{t('cardTitle')}</span>
          <span className={css.muted}>{t('cardDescription')}</span>
        </span>
        <span className={css.count}>{servers.length}</span>
      </button>
      {open
        ? (
          <div className={css.cardBody}>
            {!writable && settings.status === 'ready' ? <p className={css.muted}>{t('readOnly')}</p> : null}
            {servers.length === 0 && settings.status === 'ready' ? <p className={css.muted}>{t('cardEmpty')}</p> : null}
            <ul className={css.plain}>
              {servers.map(server => (
                <li key={server.id} className={css.serverRow} data-testid="library-settings-server">
                  <strong>{server.displayName}</strong>
                  <code className={css.code}>{server.modelHost ?? '—'}</code>
                  <span className={css.muted}>{server.controller?.mode === 'ssh' ? `ssh ${server.controller.sshDestination ?? ''} ${server.controller.sshCommand ?? ''}` : server.controller?.mode === 'http' ? server.controller.httpURL : t('modeNone')}</span>
                  <button type="button" className={css.secondary} onClick={() => { void face.store.refresh(server.id).then(() => { face.openLibrary() }) }} data-testid="library-settings-check">{t('check')}</button>
                  <button type="button" className={css.ghost} disabled={!writable || saving} onClick={() => { void write(servers.filter(s => s.id !== server.id)) }}>{t('remove')}</button>
                </li>
              ))}
            </ul>
            <form className={css.form} onSubmit={(event) => { event.preventDefault(); void add() }} data-testid="library-settings-form">
              {field('name', 'fieldName')}
              {field('modelHost', 'fieldModelHost', 'fieldModelHostHint', '192.168.1.20')}
              <label className={css.field}>
                <span className={css.label}>{t('fieldMode')}</span>
                <select className={css.input} value={form.mode} disabled={!writable} onChange={(event) => { setForm({ ...form, mode: event.target.value }) }} data-testid="library-field-mode">
                  <option value="ssh">{t('modeSsh')}</option>
                  <option value="http">{t('modeHttp')}</option>
                  <option value="none">{t('modeNone')}</option>
                </select>
              </label>
              {form.mode === 'ssh' ? field('sshDestination', 'fieldSshDestination', 'fieldSshDestinationHint', 'gpu-server') : null}
              {form.mode === 'ssh' ? field('sshCommand', 'fieldSshCommand') : null}
              {form.mode === 'http' ? field('httpURL', 'fieldHttpUrl', undefined, 'http://10.0.0.5:18190') : null}
              {form.mode === 'http' ? field('tokenEnv', 'fieldTokenEnv', 'fieldTokenEnvHint', 'AUDIO_CONTROLLER_TOKEN') : null}
              {field('catalogFile', 'fieldCatalogFile', 'fieldCatalogFileHint')}
              {field('apiKeyEnv', 'fieldApiKeyEnv', 'fieldTokenEnvHint')}
              <div className={css.actions}>
                <span role="status" className={css.muted} data-testid="library-settings-status">{status}</span>
                <button type="submit" className={css.primary} disabled={!writable || saving}>{saving ? t('saving') : t('add')}</button>
              </div>
            </form>
          </div>
        )
        : null}
    </li>
  )
}
