/** Sidebar panel-list icon for the audio model library (waveform over a stack). */
export function SidebarIcon(props: { size?: number, active?: boolean }) {
  const size = props.size ?? 16
  return (
    <svg width={size} height={size} viewBox="0 0 16 16" fill="none" aria-hidden="true" data-testid="library-sidebar-icon" data-active={props.active === true}>
      <path d="M2 9.5V6.5M4.5 11V5M7 12.5V3.5M9.5 10V6M12 11.5V4.5M14 9V7" stroke="currentColor" strokeWidth="1.3" strokeLinecap="round" />
    </svg>
  )
}
