export interface Snapshot {
  status: 'loading' | 'ready' | 'absent' | 'error'
  doc: LibraryDocument | null
  message?: string
  busy: Record<string, boolean>
  lastError: { code: string, message: string, extra?: Record<string, unknown> } | null
}

export class ActionError extends Error {
  constructor(public code: string, message: string, public extra: Record<string, unknown> = {}) {
    super(message)
  }
}

async function post(path: string, body: unknown): Promise<any> {
  const response = await fetch(`${API}/${path}`, { method: 'POST', credentials: 'include', headers: { 'content-type': 'application/json' }, body: JSON.stringify(body) })
  const json = await response.json().catch(() => undefined) as any
  if (!response.ok || json?.ok === false) {
    const { code, message, ...extra } = json?.error ?? {}
    throw new ActionError(String(code ?? `HTTP_${response.status}`), String(message ?? `HTTP ${response.status}`), extra)
  }
  return json
}

export class LibraryStore {
  private snapshot: Snapshot = { status: 'loading', doc: null, busy: {}, lastError: null }
  private readonly listeners = new Set<() => void>()
  private feed: AbortController | undefined
  private cursor: number | undefined
  private disposed = false
  private reloadTimer: ReturnType<typeof setTimeout> | undefined

  getSnapshot = (): Snapshot => this.snapshot

  subscribe = (listener: () => void): (() => void) => {
    this.listeners.add(listener)
    if (this.listeners.size === 1) this.openFeed()
    return () => {
      this.listeners.delete(listener)
      if (this.listeners.size === 0) this.closeFeed()
    }
  }

  dispose(): void {
    this.disposed = true
    this.closeFeed()
    this.listeners.clear()
  }

  private publish(patch: Partial<Snapshot>): void {
    if (this.disposed) return
    this.snapshot = { ...this.snapshot, ...patch }
    for (const listener of this.listeners) listener()
  }

  /** Cached host state only; contacts no server. */
  async load(): Promise<void> {
    try {
      const response = await fetch(`${API}/library`, { credentials: 'include' })
      if (response.status === 404) { this.publish({ status: 'absent', doc: null }); return }
      if (!response.ok) { this.publish({ status: 'error', message: `HTTP ${response.status}` }); return }
      this.publish({ status: 'ready', doc: await response.json() as LibraryDocument })
    } catch (error) {
      this.publish({ status: 'error', message: error instanceof Error ? error.message : String(error) })
    }
  }

  private scheduleLoad(): void {
    if (this.reloadTimer !== undefined) return
    this.reloadTimer = setTimeout(() => { this.reloadTimer = undefined; void this.load() }, 120)
  }

  private openFeed(): void {
    if (this.feed !== undefined || this.disposed) return
    const controller = new AbortController()
    this.feed = controller
    void (async () => {
      let backoff = 500
      while (!controller.signal.aborted) {
        try {
          const url = `${API}/events${this.cursor === undefined ? '' : `?after=${this.cursor}`}`
          const response = await fetch(url, { credentials: 'include', signal: controller.signal })
          if (!response.ok || response.body === null) throw new Error(`HTTP ${response.status}`)
          backoff = 500
          const reader = response.body.getReader()
          const decoder = new TextDecoder()
          let buffer = ''
          for (;;) {
            const { value, done } = await reader.read()
            if (done) break
            buffer += decoder.decode(value, { stream: true })
            let newline = buffer.indexOf('\n')
            while (newline >= 0) {
              const line = buffer.slice(0, newline).trim()
              buffer = buffer.slice(newline + 1)
              newline = buffer.indexOf('\n')
              if (line === '') continue
              const event = JSON.parse(line) as { type: string, cursor?: number }
              if (typeof event.cursor === 'number') this.cursor = event.cursor
              if (event.type !== 'ping') this.scheduleLoad()
            }
          }
        } catch {
          if (controller.signal.aborted) return
        }
        await new Promise(resolve => setTimeout(resolve, backoff))
        backoff = Math.min(backoff * 2, 10_000)
      }
    })()
    void this.load()
  }

  private closeFeed(): void {
    this.feed?.abort()
    this.feed = undefined
  }

  private async run<T>(key: string, action: () => Promise<T>): Promise<T | undefined> {
    this.publish({ busy: { ...this.snapshot.busy, [key]: true }, lastError: null })
    try {
      const result = await action()
      await this.load()
      return result
    } catch (error) {
      const failure = error instanceof ActionError ? { code: error.code, message: error.message, extra: error.extra } : { code: 'NETWORK', message: error instanceof Error ? error.message : String(error) }
      this.publish({ lastError: failure })
      await this.load()
      return undefined
    } finally {
      const busy = { ...this.snapshot.busy }
      delete busy[key]
      this.publish({ busy })
    }
  }

  refresh(serverId?: string) { return this.run(`refresh:${serverId ?? '*'}`, () => post('refresh', serverId ? { serverId } : {})) }
  activate(body: { serverId: string, rowId: string, recipeId?: string, tasks?: string[], confirmCancelRunning?: boolean }) { return this.run(`activate:${body.serverId}`, () => post('activate', body)) }
  bind(body: { serverId: string, rowId: string, recipeId?: string, tasks?: string[] }) { return this.run(`bind:${body.serverId}`, () => post('bind', body)) }
  cancel(serverId: string, jobId: string) { return this.run(`cancel:${serverId}`, () => post('cancel', { serverId, jobId })) }
  deactivate(serverId: string, recipeId: string) { return this.run(`deactivate:${serverId}`, () => post('deactivate', { serverId, recipeId })) }
  clearError() { this.publish({ lastError: null }) }
}

/** Library-managed provider → recipe/model view (for the composer chip). */
export function findLibraryModel(doc: LibraryDocument | null, provider: string, model: string): { row: RowView, recipe: RecipeView } | undefined {
  if (doc === null) return undefined
  for (const row of doc.rows) {
    for (const recipe of row.recipes) {
      if (recipe.provider === provider && (recipe.models.some(m => m.id === model) || model.startsWith(`${recipe.recipeId}--`))) return { row, recipe }
    }
  }
  return undefined
}
