/**
 * Composer chip (`conversation.input.left`): the activation state of the session's library-managed
 * model, or an "Audio models" entry once a server is configured. Clicking opens the library with
 * this conversation as the target. It never activates or selects anything by itself.
 */

import { useSyncExternalStore } from 'react'
import type { LibraryStore } from './store.ts'
import { activationState } from './service.ts'
import { findLibraryModel } from './store.ts'
import { format, type LibraryKey } from './locale.ts'
import css from './library.module.css'

export interface ChipFace {
  store: LibraryStore
  open(options: { sessionId: string, rowId?: string }): void
}

export function LibraryChip(props: any) {
  const t = (key: LibraryKey, values?: Record<string, string>) => format(props.t(key), values)
  const face: ChipFace = props.libraryChip
  const snapshot = useSyncExternalStore(face.store.subscribe, face.store.getSnapshot)
  const selection = props.useProjection('modelSelection', (value: any) => value?.next ?? value?.lastUsed ?? null) as { provider: string, model: string } | null
  const doc = snapshot.doc
  if (doc === null || !doc.configured) return null
  const found = selection === null ? undefined : findLibraryModel(doc, selection.provider, selection.model)
  if (found === undefined || selection === null) {
    return (
      <button type="button" className={css.chip} title={t('chipOpen')} aria-label={t('chipOpen')} onClick={() => { face.open({ sessionId: props.sessionId }) }} data-testid="library-chip">
        <span className={css.chipDot} aria-hidden="true" />
        {t('chipLabel')}
      </button>
    )
  }
  const model = found.recipe.models.find(m => m.id === selection.model)
  if (model?.liveOnly === true) {
    // I2-A #2: a live-only model as the conversation model makes every prompt fail; say so and route to the library.
    return (
      <button type="button" className={`${css.chip} ${css.chipBad}`} title={t('liveOnly')} onClick={() => { face.open({ sessionId: props.sessionId, rowId: found.row.id }) }} data-testid="library-chip" data-activation="live-only">
        <span className={css.chipDot} aria-hidden="true" />
        {t('chipLiveOnly', { model: model.name ?? model.id })}
      </button>
    )
  }
  const activation = activationState(doc, selection.provider, selection.model)
  const stateText = activation.state === 'ready' ? t('stateReady')
    : activation.state === 'loading' || activation.state === 'queued' ? t('stateLoading')
      : activation.state === 'error' ? `${activation.code}`
        : activation.state === 'busy' ? t('switchingBlocked', { reason: activation.detail ?? activation.reason })
          : activation.state === 'stopping' ? t('stateStale') : t('stateCold')
  return (
    <button
      type="button"
      className={`${css.chip} ${activation.state === 'ready' ? css.chipReady : activation.state === 'error' ? css.chipBad : ''}`}
      title={t('chipOpen')}
      onClick={() => { face.open({ sessionId: props.sessionId, rowId: found.row.id }) }}
      data-testid="library-chip"
      data-activation={activation.state}
    >
      <span className={css.chipDot} aria-hidden="true" />
      {t('chipModelState', { model: model?.name ?? found.row.displayName, state: stateText })}
    </button>
  )
}
