/**
 * Full-page audio model library (`main` key `model-library`, sidebar entry "Audio models").
 * Browsing is local; Refresh / Activate / Cancel / Unload are explicit actions through host routes.
 * Using a model in a conversation is the standard Session model selection.
 */

import { useEffect, useMemo, useState, useSyncExternalStore } from 'react'
import type { Job, LibraryStore, RecipeView, RowView, ServerView, Snapshot, SpeedMetric } from './store.ts'
import { bytes, duration, format, type LibraryKey } from './locale.ts'
import css from './library.module.css'

export interface NavState {
  sessionId: string | undefined
  rowId: string | undefined
}

export class NavStore {
  private state: NavState = { sessionId: undefined, rowId: undefined }
  private readonly listeners = new Set<() => void>()
  getSnapshot = (): NavState => this.state
  subscribe = (listener: () => void): (() => void) => { this.listeners.add(listener); return () => { this.listeners.delete(listener) } }
  set(patch: Partial<NavState>): void {
    this.state = { ...this.state, ...patch }
    for (const listener of this.listeners) listener()
  }
}

export interface LibraryViewFace {
  store: LibraryStore
  nav: NavStore
  selectModel(sessionId: string, provider: string, model: string): Promise<{ ok: boolean, message?: string }>
  sessionTitle(sessionId: string): string | undefined
}

type T = (key: LibraryKey, values?: Record<string, string | number>) => string

const PHASES = ['queued', 'preflight', 'draining', 'stopping', 'starting', 'loading', 'verifying', 'ready']
const TERMINAL = new Set(['ready', 'stopped', 'failed', 'cancelled', 'refused'])

function evidenceLabel(t: T, state: string): string {
  switch (state) {
    case 'pass': return t('evidencePass')
    case 'fail': return t('evidenceFail')
    case 'blocked': return t('evidenceBlocked')
    case 'unsupported_reviewed': return t('capUnsupportedReviewed')
    default: return t('evidenceUnverified')
  }
}

function residencyLabel(t: T, residency: string): string {
  switch (residency) {
    case 'active': return t('residencyActive')
    case 'loading': return t('residencyLoading')
    case 'cold': return t('residencyCold')
    case 'static': return t('residencyStatic')
    default: return t('residencyNoRecipe')
  }
}

/** Only catalog/owner evidence counts; a mock or live runtime state never turns a declared task into a pass. */
function taskHasPass(row: RowView, task: string): boolean {
  const ev = row.taskAcceptance?.[task]
  return ev?.backend.state === 'pass' || ev?.desktop.state === 'pass'
}

function reasonLabel(t: T, reason: string | null): string {
  const key = `reason_${reason}` as LibraryKey
  return reason === null ? '' : (t(key) === key ? reason : t(key))
}

function unknownish(t: T, value: string | null | undefined): string {
  if (value === null || value === undefined) return t('notInCatalog')
  return value === 'unknown' ? t('unknown') : value
}

function useNow(active: boolean): number {
  const [now, setNow] = useState(() => Date.now())
  useEffect(() => {
    if (!active) return
    const timer = setInterval(() => { setNow(Date.now()) }, 1000)
    return () => { clearInterval(timer) }
  }, [active])
  return now
}

function JobBanner({ t, server, store, snapshot }: { t: T, server: ServerView, store: LibraryStore, snapshot: Snapshot }) {
  const job: Job | null = server.job
  const running = job !== null && !TERMINAL.has(job.phase)
  const now = useNow(running)
  if (job === null) return null
  const started = Date.parse(job.createdAt ?? '')
  const elapsed = Number.isFinite(started) ? (now - started) / 1000 : NaN
  const reached = new Set(job.history.map(h => h.phase))
  const stepIndex = PHASES.indexOf(job.phase === 'restoring' ? 'stopping' : job.phase)
  const title = format(t('jobTitle'), { kind: job.kind === 'activate' ? t('activate') : t('deactivate'), recipe: job.recipeId })
  return (
    <section className={`${css.job} ${job.phase === 'failed' || job.phase === 'refused' ? css.jobBad : ''}`} data-testid="library-job" data-phase={job.phase} data-recipe={job.recipeId} data-job={job.jobId} data-kind={job.kind} aria-live="polite">
      <div className={css.jobHead}>
        <strong>{title}</strong>
        <span className={css.phase}>{t(`phase_${job.phase}` as LibraryKey)}</span>
        {running
          ? <span className={css.muted}>{job.typicalLoadSeconds ? format(t('elapsed'), { elapsed: duration(elapsed), typical: duration(job.typicalLoadSeconds) }) : format(t('elapsedOnly'), { elapsed: duration(elapsed) })}</span>
          : null}
        {running
          ? <button type="button" className={css.ghost} disabled={snapshot.busy[`cancel:${server.id}`] === true} onClick={() => { void store.cancel(server.id, job.jobId) }} data-testid="library-job-cancel">{t('cancel')}</button>
          : null}
      </div>
      {job.kind === 'activate'
        ? (
          <ol className={css.steps}>
            {PHASES.filter(phase => running || reached.has(phase)).map((phase, index) => (
              <li key={phase} className={running && phase === job.phase ? css.stepNow : reached.has(phase) && (index < stepIndex || !running) ? css.stepDone : css.step}>{t(`phase_${phase}` as LibraryKey)}</li>
            ))}
          </ol>
        )
        : null}
      {job.error
        ? (
          <div className={css.error} role="alert">
            <p>{format(t('errorLine'), { code: job.error.code, message: job.error.message })}</p>
            {job.error.connections ? <p>{format(t('busyConnections'), { detail: Object.entries(job.error.connections).map(([k, v]) => `${k}: ${v}`).join(', ') })}</p> : null}
            {job.error.logTail ? <details><summary>{t('logTail')}</summary><pre className={css.pre}>{job.error.logTail}</pre></details> : null}
          </div>
        )
        : null}
      {(job.restored ?? []).map(item => <p key={item.recipeId} className={item.ok ? css.ok : css.bad}>{format(t(item.ok ? 'restoredOk' : 'restoredFail'), { recipe: item.recipeId })}</p>)}
    </section>
  )
}

function RecipeCard({ t, face, row, recipe, server, snapshot, adapterLegacy }: { t: T, face: LibraryViewFace, row: RowView, recipe: RecipeView, server: ServerView | undefined, snapshot: Snapshot, adapterLegacy: boolean }) {
  const nav = useSyncExternalStore(face.nav.subscribe, face.nav.getSnapshot)
  const [chosen, setChosen] = useState<string[] | undefined>(undefined)
  const [useStatus, setUseStatus] = useState<string>('')
  const bindable = recipe.tasks.filter(task => task.bindable).map(task => task.id)
  const selected = chosen ?? bindable
  const controllerMode = server?.controller.mode ?? 'none'
  const jobRunning = server?.job !== null && server?.job !== undefined && !TERMINAL.has(server.job.phase)
  const busyError = snapshot.lastError?.code === 'LOCAL_BUSY'
  const activate = (confirmCancelRunning = false) => {
    void face.store.activate({ serverId: recipe.serverId, rowId: row.id, recipeId: recipe.recipeId, tasks: selected, ...(confirmCancelRunning ? { confirmCancelRunning } : {}) })
  }
  const use = async (model: RecipeView['models'][number]) => {
    if (nav.sessionId === undefined) { setUseStatus(t('noTarget')); return }
    const result = await face.selectModel(nav.sessionId, recipe.provider, model.id)
    setUseStatus(result.ok ? format(t('useDone'), { model: model.name ?? model.id }) : format(t('saveFailed'), { message: result.message ?? '' }))
  }
  return (
    <li className={css.recipe} data-testid="library-recipe" data-recipe={recipe.recipeId} data-activation={recipe.activation.state}>
      <div className={css.recipeHead}>
        <span className={css.recipeName}>{recipe.displayName}</span>
        <span className={`${css.badge} ${recipe.healthy ? css.badgeOk : ''}`}>{recipe.healthy ? t('alreadyRunning') : residencyLabel(t, recipe.active ? 'loading' : 'cold')}</span>
        {recipe.memoryGiB ? <span className={css.muted}>{recipe.memoryGiB} GiB</span> : null}
        {recipe.typicalLoadSeconds ? <span className={css.muted}>~{duration(recipe.typicalLoadSeconds)}</span> : null}
      </div>
      <fieldset className={css.tasks}>
        <legend className={css.label}>{t('chooseTasks')}</legend>
        {recipe.tasks.map(task => (
          <label key={task.id} className={`${css.task} ${task.bindable ? '' : css.taskOff}`} title={task.bindable ? task.feature : format(t('taskUnavailable'), { reason: reasonLabel(t, task.reason) })}>
            <input
              type="checkbox"
              disabled={!task.bindable}
              checked={task.bindable && selected.includes(task.id)}
              onChange={(event) => { setChosen(event.target.checked ? [...selected, task.id] : selected.filter(id => id !== task.id)) }}
            />
            <span>{task.id}</span>
            {!task.bindable ? <span className={css.muted}>{reasonLabel(t, task.reason)}</span> : null}
            {task.bindable && !taskHasPass(row, task.id) ? <span className={css.taskNote} data-testid="library-task-declared" data-task={task.id}>{t('taskDeclaredOnly')}</span> : null}
            {recipe.endpointNotes?.[task.id] ? <span className={css.taskNote} data-testid="library-endpoint-note">{recipe.endpointNotes[task.id]}</span> : null}
          </label>
        ))}
      </fieldset>
      {recipe.notes ? <p className={css.ownerNote} data-testid="library-recipe-notes"><strong>{t('ownerNotes')}:</strong> {recipe.notes}</p> : null}
      {speedAdvisories(row, recipe.recipeId).some(a => a.recipeId === recipe.recipeId) ? <SpeedLine t={t} row={{ ...row, advisories: (row.advisories ?? []).filter(a => a.recipeId === recipe.recipeId) }} recipeId={recipe.recipeId} /> : null}
      {recipe.busy && recipe.busy.total > 0 ? <p className={css.muted} data-testid="library-recipe-busy">{format(t('busyRunning'), { count: recipe.busy.total })}</p> : null}
      {recipe.planError ? <p className={css.bad}>{format(t('errorLine'), { code: recipe.planError.code, message: recipe.planError.message })}</p> : null}
      {adapterLegacy && recipe.tasks.some(task => task.reason === 'ADAPTER_MODE_UNSUPPORTED') ? <p className={css.muted}>{t('adapterLegacy')}</p> : null}
      <div className={css.actions}>
        {controllerMode !== 'none' && !recipe.healthy
          ? <button type="button" className={css.primary} title={t('activateHint')} disabled={jobRunning || selected.length === 0 || snapshot.busy[`activate:${recipe.serverId}`] === true} onClick={() => { activate() }} data-testid="library-activate">{snapshot.busy[`activate:${recipe.serverId}`] ? t('activating') : t('activate')}</button>
          : null}
        {controllerMode !== 'none' && recipe.healthy && !recipe.usable
          ? <button type="button" className={css.primary} disabled={jobRunning || selected.length === 0} onClick={() => { void face.store.bind({ serverId: recipe.serverId, rowId: row.id, recipeId: recipe.recipeId, tasks: selected }) }} data-testid="library-bind">{t('activate')}</button>
          : null}
        {controllerMode !== 'none' && recipe.active
          ? <button type="button" className={css.ghost} disabled={jobRunning} onClick={() => { void face.store.deactivate(recipe.serverId, recipe.recipeId) }} data-testid="library-deactivate">{t('deactivate')}</button>
          : null}
        {controllerMode === 'none' ? <span className={css.muted}>{t('controllerNone')}</span> : null}
        {busyError ? <button type="button" className={css.ghost} onClick={() => { activate(true) }}>{t('confirmCancelRunning')}</button> : null}
      </div>
      {recipe.models.length > 0
        ? (
          <ul className={css.models} aria-label={t('models')}>
            {recipe.models.map(model => (
              <li key={model.id} className={css.model} data-testid="library-model" data-model={model.id}>
                <code className={css.code}>{model.id}</code>
                <span>{model.tasks.join(', ')}</span>
                {model.inputSampleRate && model.outputSampleRate ? <span className={css.muted}>{format(t('sampleRates'), { input: model.inputSampleRate, output: model.outputSampleRate })}</span> : null}
                {model.referenceAudio === 'missing' ? <span className={css.bad}>{t('referenceMissing')}</span> : null}
                {typeof model.requestOptionCount === 'number' ? <span className={css.muted} data-testid="library-request-options" data-statuses={JSON.stringify(model.requestOptionStatuses ?? null)}>{format(t('requestOptionsDeclared'), { count: model.requestOptionCount })}{model.requestOptionStatuses ? ` · ${format(t('requestOptionStatuses'), { statuses: Object.entries(model.requestOptionStatuses).map(([k, n]) => `${k} ${n}`).join(', ') })}` : ''}</span> : null}
                {model.liveOnly
                  ? <span className={css.muted} data-testid="library-live-only">{t('liveOnly')}</span>
                  : <button type="button" className={css.secondary} disabled={!recipe.usable} title={format(t('useHint'), { model: model.name ?? model.id })} onClick={() => { void use(model) }} data-testid="library-use">{t('useHere')}</button>}
              </li>
            ))}
          </ul>
        )
        : null}
      {useStatus !== '' ? <p className={css.muted} role="status">{useStatus}</p> : null}
    </li>
  )
}

function RowDetails({ t, face, row, doc, snapshot, onClose }: { t: T, face: LibraryViewFace, row: RowView, doc: NonNullable<Snapshot['doc']>, snapshot: Snapshot, onClose: () => void }) {
  const adapterLegacy = doc.adapter.binding === 'settings'
  return (
    <aside className={css.detail} data-testid="library-detail" data-row={row.id}>
      <div className={css.detailHead}>
        <h2 className={css.detailTitle}>{row.displayName}</h2>
        <button type="button" className={css.ghost} onClick={onClose}>{t('close')}</button>
      </div>
      <dl className={css.facts}>
        <dt>{t('repository')}</dt><dd><code className={css.code}>{unknownish(t, row.repo)}</code></dd>
        <dt>{t('revision')}</dt><dd><code className={css.code}>{unknownish(t, row.revision)}</code></dd>
        <dt>{t('architecture')}</dt><dd>{row.engine ?? t('notInCatalog')} · {unknownish(t, row.architecture)}</dd>
        <dt>{t('access')}</dt><dd>{unknownish(t, row.access)}{row.accessPrerequisite ? ` — ${row.accessPrerequisite}` : ''}</dd>
        <dt>{t('license')}</dt><dd>{unknownish(t, row.license)}</dd>
        <dt>{t('colStatus')}</dt><dd>{row.lifecycle}{row.lifecycleReason ? ` — ${row.lifecycleReason}` : ''}{row.blockedPrerequisite ? ` — ${t('prerequisite')}: ${row.blockedPrerequisite}` : ''}</dd>
        <dt>{t('colDownload')}</dt><dd>{row.download.state}{row.download.localBytes !== null ? ` · ${bytes(row.download.localBytes)}${row.download.expectedBytes !== null ? ` / ${bytes(row.download.expectedBytes)}` : ''}` : ''}</dd>
        <dt>{t('colEvidence')}</dt><dd>{t('backend')} {evidenceLabel(t, row.acceptance.backend.state)} · {t('desktop')} {evidenceLabel(t, row.acceptance.desktop.state)}{row.acceptance.missingModes.length > 0 ? ` · ${row.acceptance.missingModes.join(', ')}` : ''}</dd>
        <dt>{t('hardware')}</dt><dd>{unknownish(t, row.hardware.feasibility)}{row.hardware.estimatedWeightGiB !== null ? ` · ${row.hardware.estimatedWeightGiB} GiB` : ''}</dd>
        <dt>{t('modalities')}</dt><dd>{row.modalities.input.join(', ') || t('notInCatalog')} → {row.modalities.output.join(', ') || t('notInCatalog')}</dd>
        {row.testedImage ? (<><dt>{t('testedImage')}</dt><dd><code className={css.code}>{row.testedImage}</code></dd></>) : null}
        {row.weightIdentity
          ? (
            <><dt>{t('resultScope')}</dt><dd data-testid="library-result-scope">
              {format(t('weightsLine'), { precision: row.weightIdentity.precision ?? t('unknown'), method: row.weightIdentity.quantizationMethod ?? t('unknown'), base: row.weightIdentity.baseCheckpoint ?? t('unknown'), relation: row.weightIdentity.publisherRelation ?? t('unknown') })}
              {row.weightIdentity.resultScope ? <span className={css.taskNote}>{row.weightIdentity.resultScope}</span> : null}
            </dd></>
          )
          : null}
        {row.dependencyCompleteness && !row.dependencyCompleteness.complete ? (<><dt>{t('dependencies')}</dt><dd className={css.bad}>{format(t('dependencyOpen'), { count: row.dependencyCompleteness.open })}</dd></>) : null}
      </dl>
      {(row.runtimeDefects ?? []).length > 0
        ? (
          <div className={css.error} data-testid="library-runtime-defects">
            <strong>{t('runtimeDefects')}</strong>
            {(row.runtimeDefects ?? []).map(d => <p key={d.id ?? d.summary ?? ''}>{d.summary}{d.upstreamIssue?.url ? ` — ${d.upstreamIssue.url} (${d.upstreamIssue.state ?? t('unknown')})` : ''}{d.upstreamFix?.url ? ` — ${d.upstreamFix.url} (${d.upstreamFix.state ?? t('unknown')})` : ''}</p>)}
          </div>
        )
        : null}
      <EvidenceDetails t={t} row={row} />
      <h3 className={css.h3}>{t('runtimes')}</h3>
      {row.recipes.length === 0 ? <p className={css.muted}>{t('noRecipes')}</p> : null}
      <ul className={css.recipes}>
        {row.recipes.map(recipe => <RecipeCard key={`${recipe.serverId}/${recipe.recipeId}`} t={t} face={face} row={row} recipe={recipe} server={doc.servers.find(s => s.id === recipe.serverId)} snapshot={snapshot} adapterLegacy={adapterLegacy} />)}
      </ul>
      {row.staticRoutes.length > 0 ? <p className={css.muted}>{row.staticRoutes.map(r => `${r.provider}/${r.model} (${r.mode})`).join(' · ')}</p> : null}
      <h3 className={css.h3}>{t('streamingModes')}</h3>
      {row.streamingModes.length === 0
        ? <p className={css.muted}>{t('notInCatalog')}</p>
        : (
          <div className={css.scroll}>
            <table className={css.table}>
              <tbody>
                {row.streamingModes.map(mode => (
                  <tr key={mode.mode}>
                    <td><code className={css.code}>{mode.mode}</code></td>
                    <td>{t('runtimeSupport')}: {unknownish(t, mode.runtimeSupport)}</td>
                    <td>{t('backend')}: {evidenceLabel(t, mode.backend.state)}</td>
                    <td>{t('desktop')}: {evidenceLabel(t, mode.desktop.state)}</td>
                    <td className={css.muted}>{[mode.backend.notes, mode.desktop.notes].filter(Boolean).join(' · ')}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      {row.endpoints.length > 0
        ? (<><h3 className={css.h3}>{t('endpoints')}</h3><ul className={css.plain}>{row.endpoints.map((e, i) => <li key={i}><code className={css.code}>{e.task ?? '?'} {e.path ?? ''} {e.protocol}</code> {e.inputSampleRate ?? ''}{e.outputSampleRate ? ` → ${e.outputSampleRate}` : ''}</li>)}</ul></>)
        : null}
      {row.dependencies.length > 0
        ? (<><h3 className={css.h3}>{t('dependencies')}</h3><ul className={css.plain}>{row.dependencies.map((d, i) => <li key={i}>{d.role ?? '?'} · <code className={css.code}>{d.asset ?? '?'}</code>{d.required ? ' *' : ''} · {d.downloadState ?? t('unknown')}</li>)}</ul></>)
        : null}
      {row.sources.length > 0
        ? (<><h3 className={css.h3}>{t('sources')}</h3><ul className={css.plain}>{row.sources.map((s, i) => <li key={i}><code className={css.code}>{s.kind}: {s.ref}</code></li>)}</ul></>)
        : null}
      {row.notes ? (<><h3 className={css.h3}>{t('notes')}</h3><p className={css.muted}>{row.notes}</p></>) : null}
    </aside>
  )
}

function countsText(counts: Record<string, number> | undefined, total: number | null | undefined): string {
  const parts = Object.entries(counts ?? {}).map(([state, n]) => `${state} ${n}`)
  return `${total ?? '?'}${parts.length > 0 ? ` (${parts.join(', ')})` : ''}`
}

function speedAdvisories(row: RowView, recipeId?: string) {
  return (row.advisories ?? []).filter(a => (a.kind === 'below-realtime' || a.kind === 'speed-metric') && (recipeId === undefined || a.recipeId === recipeId || a.scope !== 'recipe'))
}

function metricText(t: T, m: SpeedMetric): string {
  const value = m.range ? `${m.range[0]}–${m.range[1]}` : String(m.value)
  const cls = { 'below-realtime': 'speedClass_below', 'at-or-above-realtime': 'speedClass_above', mixed: 'speedClass_mixed', unclassified: 'speedClass_unclassified', latency: 'speedClass_latency' }[m.classification] as LibraryKey
  const parts = [
    format(t('speedMetricLine'), { metric: m.metric, value, unit: m.unit ?? '?', formula: m.formula ?? '?' }),
    t(cls),
    format(t('speedKind'), { kind: m.measurementKind }),
    [m.statistic, m.n !== null ? `n=${m.n}` : null, m.phase, m.hardware].filter(Boolean).join(' · '),
    m.conditions ?? '',
    m.rawLabel || m.rawValue ? format(t('speedRaw'), { label: m.rawLabel ?? '', value: m.rawValue ?? '' }) : '',
  ]
  return parts.filter(p => p !== '').join(' · ')
}

function SpeedLine({ t, row, recipeId }: { t: T, row: RowView, recipeId?: string }) {
  const speed = speedAdvisories(row, recipeId)
  if (speed.length === 0) return <p className={css.muted} data-testid="library-speed-none">{t('speed')}: {t('speedNone')}</p>
  return (
    <ul className={css.plain} data-testid="library-speed">
      {speed.map((a, i) => (
        <li key={i} className={a.kind === 'below-realtime' ? css.warn : css.muted} data-kind={a.kind} data-classification={a.metric?.classification ?? (a.kind === 'below-realtime' ? 'below-realtime' : '')} data-derived={a.derived}>
          {a.kind === 'below-realtime' ? <strong>{t('speed')}: {t('speedBelowRealtime')}</strong> : <strong>{t('speed')}</strong>}
          {' · '}
          {a.metric ? metricText(t, a.metric) : format(t('speedBasisNote'), { source: t(a.source === 'recipe' ? 'sourceRecipe' : 'sourceCatalog') })}
          {a.mode ? <> · <code className={css.code}>{a.mode}</code></> : null}
          {a.task ? <> · <code className={css.code}>{a.task}</code></> : null}
          {a.layer ? <> · {t(a.layer === 'desktop' ? 'desktop' : 'backend')}</> : null}
          {a.text && !a.metric ? <span className={css.muted}> — {a.text}</span> : null}
        </li>
      ))}
    </ul>
  )
}

function EvidenceDetails({ t, row }: { t: T, row: RowView }) {
  const tasks = [...new Set([...row.tasks.map(x => x.id), ...Object.keys(row.taskAcceptance ?? {})])]
  const summary = row.acceptanceSummary
  return (
    <section data-testid="library-evidence-details">
      <h3 className={css.h3}>{t('evidenceDetails')}</h3>
      <p className={css.muted}>{t('functionVsSpeed')}</p>
      {row.acceptance.backend.notes ? <p className={row.acceptance.backend.state === 'fail' ? css.bad : css.muted} data-testid="library-row-backend-notes">{t('backend')} {evidenceLabel(t, row.acceptance.backend.state)}: {row.acceptance.backend.notes}</p> : null}
      {summary ? <p className={css.muted} data-testid="library-acceptance-summary">{format(t('summaryLine'), { tasks: countsText(summary.tasksBackend, summary.tasksTotal), modes: countsText(summary.modesBackend, summary.modesTotal), complete: t(summary.rowComplete ? 'yes' : 'no') })}</p> : null}
      <SpeedLine t={t} row={row} />
      {(row.performanceProvenance ?? []).length > 0
        ? (
          <details data-testid="library-rate-corrections">
            <summary className={css.muted}>{t('rateCorrections')} ({(row.performanceProvenance ?? []).length})</summary>
            {(row.performanceProvenance ?? []).map((p, index) => (
              <p key={index} className={css.muted}>{format(t('rateCorrectionLine'), { metric: p.metric ?? t('unknown'), scope: p.scope ?? '', key: p.key ?? '', layer: p.layer ?? '', value: Array.isArray(p.ownerValue) ? p.ownerValue.join('–') : String(p.ownerValue ?? t('unknown')), note: p.note ?? '', rawPolicy: p.rawPolicy ?? t('unknown'), items: p.items, sha: (p.correctionSha256 ?? '').slice(0, 12) })}</p>
            ))}
          </details>
        )
        : null}
      {tasks.length > 0
        ? (
          <div className={css.scroll}>
            <table className={css.table} data-testid="library-task-evidence">
              <thead><tr><th>{t('colTask')}</th><th>{t('backend')}</th><th>{t('desktop')}</th><th>{t('colNotes')}</th></tr></thead>
              <tbody>
                {tasks.map((task) => {
                  const ev = row.taskAcceptance?.[task]
                  const notes = [ev?.backend.notes, ev?.desktop.notes].filter(Boolean).join(' · ')
                  return (
                    <tr key={task} data-task={task} data-backend={ev?.backend.state ?? 'unverified'} data-desktop={ev?.desktop.state ?? 'unverified'}>
                      <td><code className={css.code}>{task}</code></td>
                      <td className={ev?.backend.state === 'fail' ? css.bad : ''}>{evidenceLabel(t, ev?.backend.state ?? 'unverified')}</td>
                      <td className={ev?.desktop.state === 'fail' ? css.bad : ''}>{evidenceLabel(t, ev?.desktop.state ?? 'unverified')}</td>
                      <td className={css.muted}>{notes}</td>
                    </tr>
                  )
                })}
              </tbody>
            </table>
          </div>
        )
        : null}
    </section>
  )
}

const uniq = (values: Array<string | null | undefined>): string[] => [...new Set(values.filter((v): v is string => typeof v === 'string' && v !== ''))].sort()

export function LibraryView(props: any) {
  const t: T = (key, values) => format(props.t(key), values)
  const face: LibraryViewFace = props.libraryView
  const snapshot = useSyncExternalStore(face.store.subscribe, face.store.getSnapshot)
  const nav = useSyncExternalStore(face.nav.subscribe, face.nav.getSnapshot)
  const [query, setQuery] = useState('')
  const [filters, setFilters] = useState({ role: '', task: '', lifecycle: '', download: '', residency: '', engine: '', streaming: '', evidence: '' })
  const [showAssets, setShowAssets] = useState(false)
  const doc = snapshot.doc

  const rows = doc?.rows ?? []
  const options = useMemo(() => ({
    role: uniq(rows.filter(r => showAssets || r.selectable).map(r => r.role)),
    task: uniq(rows.flatMap(r => r.tasks.map(x => x.id))),
    lifecycle: uniq(rows.map(r => r.lifecycle)),
    download: uniq(rows.map(r => r.download.state)),
    residency: uniq(rows.map(r => r.residency)),
    engine: uniq(rows.map(r => r.engine)),
    streaming: uniq(rows.flatMap(r => r.streamingModes.map(m => m.mode))),
    evidence: ['backend-pass', 'desktop-pass', 'unverified'],
  }), [rows, showAssets])

  const visible = rows.filter((row) => {
    if (!showAssets && !row.selectable) return false
    if (filters.role && row.role !== filters.role) return false
    if (filters.task && !row.tasks.some(x => x.id === filters.task)) return false
    if (filters.lifecycle && row.lifecycle !== filters.lifecycle) return false
    if (filters.download && row.download.state !== filters.download) return false
    if (filters.residency && row.residency !== filters.residency) return false
    if (filters.engine && row.engine !== filters.engine) return false
    if (filters.streaming && !row.streamingModes.some(m => m.mode === filters.streaming)) return false
    if (filters.evidence === 'backend-pass' && row.acceptance.backend.state !== 'pass') return false
    if (filters.evidence === 'desktop-pass' && row.acceptance.desktop.state !== 'pass') return false
    if (filters.evidence === 'unverified' && (row.acceptance.backend.state === 'pass' || row.acceptance.desktop.state === 'pass')) return false
    const q = query.trim().toLowerCase()
    if (q !== '') {
      const hay = [row.id, row.displayName, row.family, row.repo, row.architecture, ...row.tasks.map(x => x.id)].join(' ').toLowerCase()
      if (!q.split(/\s+/u).every(part => hay.includes(part))) return false
    }
    return true
  })
  const selected = rows.find(r => r.id === nav.rowId)
  const target = nav.sessionId === undefined ? undefined : face.sessionTitle(nav.sessionId) ?? nav.sessionId

  if (snapshot.status === 'absent') return <div className={css.page}><p className={css.muted}>{t('notInstalled')}</p></div>
  return (
    <div className={css.page} data-testid="model-library-view">
      <header className={css.header}>
        <div>
          <h1 className={css.title}>{t('title')}</h1>
          <p className={css.muted}>{t('subtitle')}</p>
          {target !== undefined ? <p className={css.target} data-testid="library-target">→ {target}</p> : null}
        </div>
        <button type="button" className={css.primary} title={t('refreshHint')} disabled={doc?.configured !== true || snapshot.busy['refresh:*'] === true} onClick={() => { void face.store.refresh() }} data-testid="library-refresh">
          {snapshot.busy['refresh:*'] ? t('refreshing') : t('refresh')}
        </button>
      </header>
      {snapshot.status === 'loading' ? <p className={css.muted}>{t('loading')}</p> : null}
      {snapshot.status === 'error' ? <p className={css.bad}>{format(t('loadFailed'), { message: snapshot.message ?? '' })}</p> : null}
      {doc !== null && !doc.configured ? <p className={css.empty} data-testid="library-no-server">{t('noServer')}</p> : null}
      {doc !== null && !doc.adapter.present ? <p className={css.bad}>{t('adapterMissing')}</p> : null}
      {snapshot.lastError
        ? (
          <div className={css.error} role="alert" data-testid="library-error">
            <p>{format(t('errorLine'), { code: String(snapshot.lastError.extra?.controllerCode ?? snapshot.lastError.code), message: snapshot.lastError.message })}</p>
            <button type="button" className={css.ghost} onClick={() => { face.store.clearError() }}>{t('close')}</button>
          </div>
        )
        : null}
      {(doc?.servers ?? []).map((server) => {
        const catalog = doc?.catalogs.find(c => c.serverId === server.id)
        const controller = server.controller
        const controllerText = controller.mode === 'none' ? t('controllerNone')
          : controller.state === 'reachable' ? t('controllerReachable')
            : controller.state === 'unreachable' ? format(t('controllerUnreachable'), { message: controller.error?.message ?? '' })
              : controller.state === 'checking' ? t('controllerChecking') : t('controllerUnknown')
        return (
          <section key={server.id} className={css.server} data-testid="library-server" data-controller={controller.state}>
            <div className={css.serverHead}>
              <strong>{server.displayName}</strong>
              <span className={controller.state === 'unreachable' ? css.bad : css.muted}>{controllerText}</span>
              {catalog?.source ? <span className={css.muted}>{format(t('catalogLine'), { version: catalog.catalogVersion ?? '?', completeness: catalog.completeness ?? '?', count: catalog.rowCount })}</span> : <span className={css.muted}>{t('catalogMissing')}</span>}
            </div>
            {catalog?.completeness && catalog.completeness !== 'full_census' && catalog.completeness !== 'refreshed_for_acceptance' ? <p className={css.muted}>{t('catalogIncomplete')}</p> : null}
            {server.switching && !server.switching.allowed ? <p className={css.bad}>{format(t('switchingBlocked'), { reason: server.switching.reason ?? server.switching.code ?? '' })}</p> : null}
            {server.foreignWorkloads.length > 0 ? <p className={css.bad}>{format(t('foreign'), { names: server.foreignWorkloads.join(', ') })}</p> : null}
            {server.bindingError ? <p className={css.bad}>{format(t('errorLine'), { code: server.bindingError.code, message: server.bindingError.message })}</p> : null}
            <JobBanner t={t} server={server} store={face.store} snapshot={snapshot} />
          </section>
        )
      })}
      {rows.length > 0
        ? (
          <>
            <div className={css.filters}>
              <input className={css.search} type="search" placeholder={t('search')} aria-label={t('search')} value={query} onChange={(event) => { setQuery(event.target.value) }} data-testid="library-search" />
              {(Object.keys(filters) as Array<keyof typeof filters>).map(key => (
                <label key={key} className={css.filter}>
                  <span className={css.label}>{t(`filter${key[0].toUpperCase()}${key.slice(1)}` as LibraryKey)}</span>
                  <select className={css.select} value={filters[key]} onChange={(event) => { setFilters({ ...filters, [key]: event.target.value }) }} data-testid={`library-filter-${key}`}>
                    <option value="">{t('any')}</option>
                    {options[key].map(value => <option key={value} value={value}>{key === 'residency' ? residencyLabel(t, value) : value}</option>)}
                  </select>
                </label>
              ))}
              <label className={css.check}><input type="checkbox" checked={showAssets} onChange={(event) => { setShowAssets(event.target.checked) }} />{t('showAssets')}</label>
              <span className={css.muted} data-testid="library-count">{format(t('results'), { count: visible.length, total: rows.filter(r => showAssets || r.selectable).length })}</span>
            </div>
            <div className={css.body}>
              <table className={css.list} data-testid="library-list">
                <thead>
                  <tr><th>{t('colModel')}</th><th>{t('colTasks')}</th><th>{t('colStatus')}</th><th>{t('colDownload')}</th><th>{t('colServer')}</th><th>{t('colEvidence')}</th></tr>
                </thead>
                <tbody>
                  {visible.map(row => (
                    <tr key={row.id} className={row.id === nav.rowId ? css.rowOn : css.row} data-testid="library-row" data-row={row.id} data-residency={row.residency} tabIndex={0} onClick={() => { face.nav.set({ rowId: row.id }) }} onKeyDown={(event) => { if (event.key === 'Enter') face.nav.set({ rowId: row.id }) }}>
                      <td>
                        <span className={css.rowName}>{row.displayName}</span>
                        {row.role === 'secondary_av' ? <> <span className={css.badge} data-testid="library-role-av">{t('roleAv')}</span></> : null}
                        {row.role === 'auxiliary_asset' ? <> <span className={css.badge} data-testid="library-role-asset">{t('roleAsset')}</span></> : null}
                        <br /><code className={css.code}>{row.id}</code>
                      </td>
                      <td className={css.chips}>{row.tasks.map(task => <span key={task.id} className={`${css.chip} ${task.bindable ? css.chipOn : ''}`} title={task.bindable ? '' : reasonLabel(t, task.reason)}>{task.id}</span>)}</td>
                      <td>{row.lifecycle}{row.blockedPrerequisite ? <><br /><span className={`${css.muted} ${css.clamp}`} title={row.blockedPrerequisite}>{row.blockedPrerequisite}</span></> : row.lifecycleReason ? <><br /><span className={`${css.muted} ${css.clamp}`} title={row.lifecycleReason}>{row.lifecycleReason}</span></> : null}</td>
                      <td>{row.download.state}{row.download.localBytes ? <><br /><span className={css.muted}>{bytes(row.download.localBytes)}</span></> : null}</td>
                      <td><span className={`${css.badge} ${row.residency === 'active' ? css.badgeOk : ''}`}>{residencyLabel(t, row.residency)}</span></td>
                      <td className={css.muted}>
                        {t('backend')} {evidenceLabel(t, row.acceptance.backend.state)}<br />{t('desktop')} {evidenceLabel(t, row.acceptance.desktop.state)}
                        {(row.advisories ?? []).some(a => a.kind === 'below-realtime') ? <><br /><span className={css.warnBadge} data-testid="library-badge-below-realtime">{t('badgeBelowRealtime')}</span></> : null}
                        {(row.advisories ?? []).some(a => a.kind === 'owner-note') ? <><br /><span className={css.badge} data-testid="library-badge-owner-notes">{t('badgeOwnerNotes')}</span></> : null}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
              {visible.length === 0 ? <p className={css.muted}>{t('noMatch')}</p> : null}
              {selected !== undefined && doc !== null ? <RowDetails t={t} face={face} row={selected} doc={doc} snapshot={snapshot} onClose={() => { face.nav.set({ rowId: undefined }) }} /> : null}
            </div>
          </>
        )
        : null}
    </div>
  )
}
