/**
 * Client service `audioModelLibrary` (CONTRACT §6.1) for other plugins, e.g. dsh-voice-capture's
 * task UI (TASK_UI_CONTRACT_PROPOSAL §D): observable activation state per Harness model id, plus
 * opening the library for a conversation. It never activates anything by itself.
 */

import { findLibraryModel, type LibraryDocument, type LibraryStore } from './store.ts'

export type ActivationState =
  | { state: 'unknown' | 'static' }
  | { state: 'cold' | 'queued' | 'stopping' | 'loading', progress?: number, detail?: string }
  | { state: 'ready', since: string }
  | { state: 'busy', reason: 'turn-running' | 'benchmark-reservation', detail?: string }
  | { state: 'error', code: string, message: string }

export interface Observable<T> {
  getSnapshot(): T
  subscribe(listener: () => void): () => void
}

export interface AudioModelLibraryFace {
  readonly contractVersion: '0.1'
  /** Observable activation state for one Harness model id (provider + model). */
  status(provider: string, model: string): Observable<ActivationState>
  /** Observable library document (null until loaded; host cache only). */
  document(): Observable<LibraryDocument | null>
  /** Open the library view, optionally targeting a conversation and a catalog row. */
  open(options?: { sessionId?: string, rowId?: string }): void
}

const ACTIVE_JOB = new Set(['queued', 'preflight', 'draining', 'stopping', 'starting', 'loading', 'verifying', 'restoring'])

/** Pure derivation (unit-tested): library document → activation state of one model id. */
export function activationState(doc: LibraryDocument | null, provider: string, model: string): ActivationState {
  if (doc === null) return { state: 'unknown' }
  const found = findLibraryModel(doc, provider, model)
  if (found === undefined) {
    return doc.rows.some(row => row.staticRoutes.some(route => route.provider === provider && route.model === model)) ? { state: 'static' } : { state: 'unknown' }
  }
  const { recipe } = found
  const server = doc.servers.find(s => s.id === recipe.serverId)
  const job = server?.job ?? null
  if (job !== null && ACTIVE_JOB.has(job.phase)) {
    if (job.kind === 'activate' && job.recipeId === recipe.recipeId) {
      if (job.phase === 'queued' || job.phase === 'preflight' || job.phase === 'draining') return { state: 'queued', detail: job.phase }
      return { state: 'loading', detail: job.phase }
    }
    if ((job.previous ?? []).includes(recipe.recipeId) || (job.kind === 'deactivate' && job.recipeId === recipe.recipeId)) return { state: 'stopping', detail: job.phase }
  }
  const entry = recipe.models.find(m => m.id === model)
  // Single-engine servers reject a live session while a chat/speech reply is still generating (I2-A #3).
  if (recipe.usable && entry?.liveOnly === true && (recipe.busy?.requests ?? 0) > 0) return { state: 'busy', reason: 'turn-running', detail: `${recipe.busy?.requests} request(s) running on ${recipe.recipeId}` }
  if (recipe.usable) return { state: 'ready', since: server?.controller.checkedAt ?? new Date(0).toISOString() }
  if (job !== null && job.recipeId === recipe.recipeId && (job.phase === 'failed' || job.phase === 'refused') && job.error) {
    return { state: 'error', code: job.error.code, message: job.error.message }
  }
  if (server?.switching && server.switching.allowed === false) return { state: 'busy', reason: 'benchmark-reservation', detail: server.switching.reason ?? server.switching.code ?? undefined }
  if (server?.bindingError) return { state: 'error', code: server.bindingError.code, message: server.bindingError.message }
  return { state: 'cold', detail: recipe.healthy ? 'running-not-bound' : 'not-loaded' }
}

export function createFace(store: LibraryStore, open: (options?: { sessionId?: string, rowId?: string }) => void): AudioModelLibraryFace {
  const cache = new Map<string, { value: ActivationState, key: string }>()
  return {
    contractVersion: '0.1',
    status(provider, model) {
      const id = `${provider}�${model}`
      return {
        getSnapshot() {
          const next = activationState(store.getSnapshot().doc, provider, model)
          const key = JSON.stringify(next)
          const previous = cache.get(id)
          if (previous !== undefined && previous.key === key) return previous.value
          cache.set(id, { value: next, key })
          return next
        },
        subscribe: listener => store.subscribe(listener),
      }
    },
    document() {
      return { getSnapshot: () => store.getSnapshot().doc, subscribe: listener => store.subscribe(listener) }
    },
    open,
  }
}
