export function format(text: string, values: Readonly<Record<string, string | number>> = {}): string {
  return text.replaceAll(/\{([^{}]+)\}/gu, (placeholder, key: string) => (values[key] === undefined ? placeholder : String(values[key])))
}

export function duration(seconds: number): string {
  if (!Number.isFinite(seconds) || seconds < 0) return '?'
  if (seconds < 90) return `${Math.round(seconds)} s`
  const minutes = Math.floor(seconds / 60)
  return `${minutes} min ${Math.round(seconds - minutes * 60)} s`
}

export function bytes(value: number | null): string {
  if (value === null) return ''
  const gib = value / 1024 ** 3
  return gib >= 1 ? `${gib.toFixed(1)} GiB` : `${(value / 1024 ** 2).toFixed(0)} MiB`
}
