/**
 * Browser half of dsh-audio-model-library (shared by Web and Desktop):
 * - `main` view `model-library` + `sidebar.panellist` entry: the full audio model catalog with search,
 *   filters, evidence, task selection, controlled activation progress/errors and "use in this conversation";
 * - `conversation.input.left` chip: the session's library model state, opening the library for that session;
 * - `settings.plugin.item` card keyed `dsh-audio-model-library`: GPU servers and activation access;
 * - client service `audioModelLibrary` (status/document/open) for other plugins (dsh-voice-capture).
 * Recording, playback, Live and task inputs stay in dsh-voice-capture; wire protocols stay in dsh-dgx-audio.
 */

import { LibraryChip, type ChipFace } from './LibraryChip.tsx'
import { LibraryView, NavStore, type LibraryViewFace } from './LibraryView.tsx'
import { SettingsCard, type SettingsFace } from './SettingsCard.tsx'
import { SidebarIcon } from './SidebarIcon.tsx'
import { createFace } from './service.ts'
import { LibraryStore } from './store.ts'
import { en, NS, zh } from './locale.ts'

const PANEL_ID = 'model-library'
const SETTINGS_NS = 'dsh-audio-model-library'

export const inject = ['slots', 'locale', 'settingsScope', 'sessions', 'remote', 'remote.session', 'layout']

export function apply(ctx: any): void {
  ctx.effect(() => ctx.locale.register(NS, { en, zh }), 'audio-model-library: dictionaries')

  const store = new LibraryStore()
  const nav = new NavStore()
  ctx.effect(() => () => { store.dispose() }, 'audio-model-library: store')
  void store.load()
  ctx.effect(() => ctx.remote.$on('settings/document-updated', () => { void store.load() }), 'audio-model-library: settings refresh')
  ctx.effect(() => ctx.remote.$on('llm/adapters-updated', () => { void store.load() }), 'audio-model-library: adapter refresh')
  ctx.effect(() => ctx.on('connection/reset', () => { void store.load() }), 'audio-model-library: reconnect refresh')

  const open = (options: { sessionId?: string, rowId?: string } = {}) => {
    nav.set({ ...(options.sessionId !== undefined ? { sessionId: options.sessionId } : {}), ...(options.rowId !== undefined ? { rowId: options.rowId } : {}) })
    ctx.layout.selectPanel(PANEL_ID)
  }

  ctx.effect(() => ctx.reflect.provide('audioModelLibrary', createFace(store, open)), 'audio-model-library: client service')

  const viewFace: LibraryViewFace = {
    store,
    nav,
    async selectModel(sessionId, provider, model) {
      try {
        const result = await ctx.remote.session.selectModel({ sessionId, provider, model })
        if (result?.ok === false) return { ok: false, message: result.error?.message ?? result.error?.code ?? 'failed' }
        return { ok: true }
      } catch (error) {
        return { ok: false, message: error instanceof Error ? error.message : String(error) }
      }
    },
    sessionTitle(sessionId) {
      const summary = ctx.sessions.list.getSnapshot().byId?.[sessionId]
      return typeof summary?.title === 'string' && summary.title !== '' ? summary.title : undefined
    },
  }

  ctx.slots.inject('main', () => ctx.slots.register({ name: 'main', key: PANEL_ID, locale: NS, inject: () => ({ libraryView: viewFace }) }, LibraryView))
  ctx.slots.inject('sidebar.panellist', () => ctx.slots.register({
    name: 'sidebar.panellist',
    id: PANEL_ID,
    order: 60,
    label: () => ctx.locale.bind(NS)('navLabel'),
  }, SidebarIcon))

  const chipFace: ChipFace = { store, open }
  ctx.slots.inject('conversation.input.left', () => ctx.slots.register({
    name: 'conversation.input.left',
    id: 'dsh-audio-model-library-chip',
    order: 95,
    locale: NS,
    inject: () => ({ libraryChip: chipFace }),
  }, LibraryChip))

  const scope = ctx.settingsScope.bind({ namespace: SETTINGS_NS })
  const settingsFace: SettingsFace = {
    scope: {
      getSnapshot: () => scope.getSnapshot(),
      subscribe: listener => scope.subscribe(listener),
      mutate: ops => scope.mutate(ops),
    },
    store,
    openLibrary: () => { ctx.layout.selectPanel(PANEL_ID) },
  }
  ctx.slots.inject('settings.plugin.item', () => ctx.slots.register({
    name: 'settings.plugin.item',
    key: SETTINGS_NS,
    locale: NS,
    inject: () => ({ librarySettings: settingsFace }),
  }, SettingsCard))
}
